add_action( 'admin_init', 'perfectpixel_block_wp_admin_non_admins', 1 );
add_filter( 'show_admin_bar', 'perfectpixel_block_wp_admin_hide_bar', 20 );

function perfectpixel_block_wp_admin_allowed() {
	$cap = trim( '{{admin_access_capability}}' );
	return current_user_can( $cap ? $cap : 'manage_options' );
}

function perfectpixel_block_wp_admin_non_admins() {
	if ( wp_doing_ajax() || wp_doing_cron() || ! is_user_logged_in() || perfectpixel_block_wp_admin_allowed() ) {
		return;
	}
	// Front-end forms post to admin-post.php; let them through.
	if ( isset( $GLOBALS['pagenow'] ) && 'admin-post.php' === $GLOBALS['pagenow'] ) {
		return;
	}
	$url = trim( '{{admin_block_redirect_url}}' );
	wp_safe_redirect( $url ? $url : home_url( '/' ) );
	exit;
}

function perfectpixel_block_wp_admin_hide_bar( $show ) {
	return ( is_user_logged_in() && ! perfectpixel_block_wp_admin_allowed() ) ? false : $show;
}
